mutations.find:
if allocator, err := p.subnetAllocator(res.ID); err == nil {
	out["AvailableIpsCount"] = allocator.Available()
}

mutations.replace:
if allocator, err := p.subnetAllocator(res.ID); err == nil {
	_ = allocator
	if prefix, prefixErr := prefixOf(res, "IpRange"); prefixErr == nil {
		if own, allocErr := network.NewAllocator(prefix, reservedPerSubnet); allocErr == nil {
			for _, vm := range p.env.Store.List(kindVM, resource.Tenant{Provider: Name}) {
				if vm.State == stateTerminated || stringOf(vm.Attrs["SubnetId"]) != res.ID {
					continue
				}
				if taken, parseErr := netip.ParseAddr(stringOf(vm.Attrs["PrivateIp"])); parseErr == nil {
					_ = own.Reserve(taken)
				}
			}
			out["AvailableIpsCount"] = own.Available()
		}
	}
}
